package nl.smartstreamlabs.sbwdroneconfig;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)
public final class CarrierFleetEvents {
    private static boolean tracked(net.minecraft.world.entity.Entity e){return e instanceof com.atsuishio.superbwarfare.entity.vehicle.DroneEntity||e instanceof Id01Entity||CarrierFleet.carrier(e);}
    @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){CarrierFleet.tick(event.getServer());}
    @net.neoforged.bus.api.SubscribeEvent public static void join(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){var e=event.getEntity();if(tracked(e)&&event.getLevel()instanceof net.minecraft.server.level.ServerLevel level&&level.getServer().overworld()!=null)CarrierFleetData.get(level).refresh(e);}
    @net.neoforged.bus.api.SubscribeEvent public static void leave(net.neoforged.neoforge.event.entity.EntityLeaveLevelEvent event){var e=event.getEntity();if(tracked(e)&&event.getLevel()instanceof net.minecraft.server.level.ServerLevel level&&level.getServer().overworld()!=null)CarrierFleetData.get(level).leaving(e);}
    @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOWEST) public static void monitor(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickItem event){if(!(event.getEntity()instanceof net.minecraft.server.level.ServerPlayer p))return;var stack=event.getItemStack();var home=CarrierFleet.home(stack);var goal=SbwCompat.getLinkedDroneUuid(stack);if(home==null||goal==null||!CarrierFleet.member(p,home,goal))return;if(SbwCompat.isUsingLinkedMonitor(stack))CarrierFleet.stopCurrent(p);else CarrierFleet.request(p,goal);event.setCanceled(true);event.setCancellationResult(net.minecraft.world.InteractionResult.SUCCESS);}
    @net.neoforged.bus.api.SubscribeEvent public static void login(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent event){if(event.getEntity()instanceof net.minecraft.server.level.ServerPlayer p)CarrierFleet.login(p);}
    @net.neoforged.bus.api.SubscribeEvent public static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent event){if(event.getEntity()instanceof net.minecraft.server.level.ServerPlayer p)CarrierFleet.logout(p);}
    @net.neoforged.bus.api.SubscribeEvent public static void dimension(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerChangedDimensionEvent event){if(event.getEntity()instanceof net.minecraft.server.level.ServerPlayer p)CarrierFleet.logout(p);}
    @net.neoforged.bus.api.SubscribeEvent public static void death(net.neoforged.neoforge.event.entity.living.LivingDeathEvent event){if(event.getEntity()instanceof net.minecraft.server.level.ServerPlayer p)CarrierFleet.logout(p);}
    @net.neoforged.bus.api.SubscribeEvent public static void stop(net.neoforged.neoforge.event.server.ServerStoppingEvent event){CarrierFleet.shutdown(event.getServer());}
}
